paper("y10computing", "A", "Practice Paper A", "4CP0 Paper 1 style · 40 minutes", [
  q("Data representation", "calculate", 2, "Convert hexadecimal 3F to denary. Show working.", [[1, "3*16|48|16*3", "3 × 16 = 48"], [1, "63", "48 + 15 = 63"]], "3 × 16 + 15 = 63"),
  q("Data representation", "calculate", 3, "An image is 800 × 600 pixels with a colour depth of 24 bits. Calculate the file size in megabytes (1 MB = 1,000,000 bytes).", [[1, "800*600|480000", "800 × 600 = 480,000 pixels"], [1, "*24|*3|bytes|11520000|1440000", "× 24 bits ÷ 8 = 1,440,000 bytes"], [1, "1.44", "1.44 MB"]], "800 × 600 × 24 = 11,520,000 bits ÷ 8 = 1,440,000 bytes = 1.44 MB"),
  q("Algorithms", "explain", 4, "Explain how a bubble sort works.", [[1, "compare&(adjacent|next|pairs)", "Compares adjacent pairs"], [1, "swap", "Swaps if in the wrong order"], [1, "pass|repeat|through the list", "Repeats passes through the list"], [1, "no swaps|until sorted", "Stops when a pass has no swaps"]], "It compares each pair of adjacent items and swaps them if they are in the wrong order. It makes repeated passes through the list; after each pass the largest item 'bubbles' to the end. It stops when a pass makes no swaps."),
  q("Networks", "compare", 4, "Compare a LAN and a WAN.", [[1, "lan&(small|single site|building)", "LAN: small area"], [1, "wan&(large|wide|country|internet)", "WAN: large geographical area"], [1, "owned|leased|telecom|infrastructure", "Ownership of infrastructure"], [1, "faster|speed|whereas", "Comparison of speed"]], "A LAN covers a small area such as one building and the hardware is usually owned by the organisation, whereas a WAN covers a large area and uses infrastructure leased from telecoms companies. LANs are usually faster."),
  q("Security", "evaluate", 6, "Evaluate methods a school could use to protect its network.", [[1, "firewall", "Firewall"], [1, "password|authentication|2fa", "Passwords / authentication"], [1, "anti-malware|antivirus", "Anti-malware"], [1, "access levels|permissions|encryption|backup", "Access levels / encryption / backups"], [1, "however|limitation|cost|training", "Limitations"], [1, "overall|in conclusion|layered|combination", "Judgement"]], "A firewall blocks unauthorised traffic; strong passwords and two-factor authentication stop unauthorised logins; anti-malware detects viruses; access levels limit what students can see; encryption and backups protect data. However, none is perfect: users need training as phishing bypasses technical measures. Overall a layered combination is best.")
], ED);
paper("y10computing", "B", "Practice Paper B", "4CP0 Paper 2 style · 40 minutes", [
  q("Programming", "give", 4, "Write Python that asks for 5 test scores and prints their average.", [[1, "for |while", "Uses a loop"], [1, "input", "Takes input"], [1, "int|float", "Converts to a number"], [1, "/5|/ 5|len", "Divides the total by 5"]], "total = 0\nfor i in range(5):\n    total += float(input(\"Score: \"))\nprint(\"Average:\", total / 5)"),
  q("Programming", "explain", 3, "Explain the purpose of validation, with an example.", [[1, "check|sensible|reasonable", "Checks data is sensible/reasonable"], [1, "range check|type check|length check|presence check", "Names a check"], [1, "not correct|accurate|guarantee", "Doesn't guarantee correctness"]], "Validation checks input is sensible before it is processed, e.g. a range check that an age is between 11 and 18. It cannot guarantee the data is actually correct."),
  q("Logic", "give", 2, "Give the output of A AND (NOT B) when A = 1, B = 0.", [[1, "not b = 1|not b is 1|not 0", "NOT B = 1"], [1, "1|true", "Output 1"]], "NOT B = 1, so 1 AND 1 = 1."),
  q("Algorithms", "describe", 4, "Describe how a binary search finds 23 in the sorted list [3, 8, 12, 17, 23, 31, 40].", [[1, "middle|17", "Checks the middle item (17)"], [1, "greater|right half|discard", "23 > 17 so discards the left half"], [1, "31", "Checks the middle of [23, 31, 40]: 31"], [1, "23|found", "23 < 31, checks 23: found"]], "Middle item is 17; 23 > 17 so search the right half [23, 31, 40]. Middle is 31; 23 < 31 so search [23]. 23 is found."),
  q("Impact", "discuss", 6, "Discuss the environmental impact of computer technology.", [[1, "e-waste|landfill|toxic", "E-waste / toxic metals"], [1, "energy|electricity|data centres|carbon", "Energy use / data centres"], [1, "mining|rare|minerals|cobalt", "Mining rare materials"], [1, "recycl|remote|paperless|smart", "Positive: recycling, remote work, smart systems"], [1, "however|on the other hand", "Balanced"], [1, "overall|in conclusion", "Conclusion"]], "Computers create e-waste with toxic metals, data centres use huge amounts of electricity, and mining rare minerals damages environments. However, technology also reduces travel through remote working, enables paperless offices and smart energy systems. Overall the impact depends on recycling and renewable energy use.")
], ED);

