paper("y10ict", "A", "Practice Paper A", "0417 Paper 1 (theory) style · 35 minutes", [
  q("Input and output devices", "give", 2, "Give two input devices used at a supermarket checkout.", [[1, "barcode", "Barcode reader"], [1, "keypad|keyboard|card reader|chip and pin|touch screen|scales", "Keypad / card reader / scales"]], "Barcode reader; chip and PIN card reader (also scales, keypad)."),
  q("Storage", "compare", 3, "Compare solid-state drives with magnetic hard disk drives.", [[1, "faster|quicker", "SSDs are faster"], [1, "no moving parts|durable|robust", "No moving parts: more durable"], [1, "expensive|cost|cheaper|capacit", "SSDs cost more per GB / HDDs larger capacity"]], "SSDs have no moving parts so they are faster to access and more durable, whereas HDDs are cheaper per gigabyte and offer larger capacities."),
  q("Safety and security", "explain", 4, "Explain how phishing works and how to protect against it.", [[1, "email|fake", "Fake email"], [1, "link|website|personal details|password", "Link to a fake site asking for details"], [1, "check sender|don't click|spam filter", "Check sender / don't click links"], [1, "report|never ask|https", "Report / legitimate companies never ask"]], "A criminal sends a fake email that looks real, with a link to a fake website asking for passwords or bank details. Protect yourself by checking the sender, not clicking links, using spam filters, and remembering banks never ask for passwords by email."),
  q("Spreadsheets", "give", 2, "Write a formula to add cells B2 to B10 and one to find their average.", [[1, "=sum(b2:b10)", "=SUM(B2:B10)"], [1, "=average(b2:b10)", "=AVERAGE(B2:B10)"]], "=SUM(B2:B10) and =AVERAGE(B2:B10)"),
  q("Effects of IT", "evaluate", 6, "Evaluate the use of online banking for customers.", [[1, "24/7|any time|convenient", "Convenient, 24/7"], [1, "travel|save time|money", "Saves travel time/costs"], [1, "fraud|hacking|phishing|security", "Risk of fraud / hacking"], [1, "internet|elderly|skills|lose contact", "Needs internet & skills / less personal"], [1, "however|on the other hand", "Balanced"], [1, "overall|in conclusion", "Judgement"]], "Online banking is convenient, available 24/7, and saves travel time and costs. However, there is a risk of fraud from phishing and hacking, and it needs internet access and IT skills, which some elderly people lack. Overall, it is beneficial if customers use strong security.")
], CA);
paper("y10ict", "B", "Practice Paper B", "0417 Paper 1 (theory) style · 35 minutes", [
  q("Networks", "describe", 3, "Describe the role of a router.", [[1, "connect&(networks|internet)", "Connects networks / to the internet"], [1, "packets|route|forward", "Routes / forwards packets"], [1, "ip address", "Uses IP addresses"]], "A router connects a LAN to other networks such as the internet. It reads the destination IP address of each data packet and forwards it along the best route."),
  q("Systems life cycle", "state", 4, "State the stages of the systems life cycle in order.", [[1, "analysis", "Analysis"], [1, "design", "Design"], [1, "development|testing", "Development and testing"], [1, "implementation", "Implementation"], [1, "documentation|evaluation", "Documentation / evaluation"]], "Analysis → design → development and testing → implementation → documentation → evaluation."),
  q("Databases", "explain", 3, "Explain why a primary key is needed in a database table.", [[1, "unique", "It is unique"], [1, "identif", "Identifies each record"], [1, "relationship|link|duplicate", "Links tables / prevents duplicates"]], "A primary key is a field with a unique value for every record, so each record can be identified. It prevents duplicate records and is used to link tables."),
  q("Health", "suggest", 3, "Suggest three ways to reduce health problems from using computers for long periods.", [[1, "break", "Regular breaks"], [1, "chair|posture|ergonomic", "Ergonomic chair / good posture"], [1, "screen|glare|filter|brightness|eye", "Anti-glare screen / eye level"], [1, "wrist|keyboard|mouse", "Wrist rest / ergonomic keyboard"]], "Take regular breaks; use an adjustable ergonomic chair with good posture; use an anti-glare screen at eye level; use a wrist rest/ergonomic keyboard."),
  q("Communication", "compare", 4, "Compare email with video conferencing for a business meeting.", [[1, "email&(not real time|asynchronous|any time|record)", "Email: not real time but leaves a record"], [1, "video&(real time|face|instant|body language)", "Video: real time, face-to-face"], [1, "equipment|webcam|bandwidth|internet|time zone", "Video needs equipment/bandwidth; time zones"], [1, "whereas|however|both", "Comparison language"]], "Email is not real-time but leaves a written record and can be read at any time, whereas video conferencing allows real-time discussion and body language. However, video needs webcams, good bandwidth and agreeing a time across time zones.")
], CA);

/* ---------------- PSYCHOLOGY (Edexcel IGCSE 4PS1) ---------------- */
paper("y10psychology", "A", "Practice Paper A", "4PS1 Paper 1 style · 40 minutes", [
  q("Research methods", "define", 2, "Define 'independent variable' and 'dependent variable'.", [[1, "independent&(change|manipulat)", "IV: what the researcher changes"], [1, "dependent&(measure)", "DV: what is measured"]], "The independent variable is what the researcher changes; the dependent variable is what is measured."),
  q("Memory", "describe", 4, "Describe the multi-store model of memory.", [[1, "sensory", "Sensory store"], [1, "short-term|short term", "Short-term memory"], [1, "long-term|long term", "Long-term memory"], [1, "rehearsal|attention|capacity|7|duration", "Attention / rehearsal / capacity and duration"]], "Information enters the sensory store; if attended to it passes to short-term memory (capacity about 7 ± 2 items, about 18–30 s). With rehearsal it transfers to long-term memory (unlimited capacity and duration)."),
  q("Research methods", "explain", 3, "Explain one strength and one weakness of laboratory experiments.", [[1, "control|variables", "Strength: control of variables"], [1, "cause and effect|replicat", "So cause and effect / replicable"], [1, "artificial|ecological validity|demand characteristics", "Weakness: artificial / low ecological validity"]], "Strength: high control over extraneous variables, so cause and effect can be established and studies replicated. Weakness: artificial settings give low ecological validity, so behaviour may not reflect real life."),
  q("Development", "describe", 3, "Describe Piaget's stages of cognitive development.", [[1, "sensorimotor", "Sensorimotor (0–2)"], [1, "pre-operational|preoperational", "Pre-operational (2–7)"], [1, "concrete operational", "Concrete operational (7–11)"], [1, "formal operational", "Formal operational (11+)"]], "Sensorimotor (0–2), pre-operational (2–7), concrete operational (7–11), formal operational (11+)."),
  q("Ethics", "evaluate", 6, "Evaluate the ethics of Milgram's obedience study.", [[1, "deception|deceived", "Deception"], [1, "distress|harm|stress", "Psychological distress"], [1, "right to withdraw|prods|continue", "Right to withdraw undermined"], [1, "debrief|follow-up|84%|glad", "Debriefed; most glad to take part"], [1, "however|on the other hand", "Balanced"], [1, "overall|in conclusion|justified", "Judgement"]], "Participants were deceived about the shocks and suffered severe distress, and the prods undermined their right to withdraw. However, they were fully debriefed, and 84% said they were glad to have taken part; the findings were valuable. Overall the study would not be allowed today, though its insights are important.")
], ED);
paper("y10psychology", "B", "Practice Paper B", "4PS1 Paper 2 style · 40 minutes", [
  q("Research methods", "explain", 3, "Explain why researchers use a random sample.", [[1, "equal chance", "Everyone has an equal chance"], [1, "bias", "Reduces researcher bias"], [1, "representative|generalis", "More representative / generalisable"]], "In a random sample everyone in the target population has an equal chance of being selected, which reduces researcher bias and makes the sample more representative, so results can be generalised."),
  q("Sleep and dreaming", "describe", 3, "Describe the stages of sleep.", [[1, "stage 1|light", "Stage 1: light sleep"], [1, "stage 3|stage 4|deep|slow wave|delta", "Deep slow-wave sleep"], [1, "rem", "REM sleep"], [1, "90 minutes|cycle", "Cycle about 90 minutes"]], "Sleep moves through stages 1–2 (light), stages 3–4 (deep, slow delta waves) and REM sleep (rapid eye movement, dreaming), repeating about every 90 minutes."),
  q("Criminal psychology", "explain", 4, "Explain social learning theory as an explanation of criminal behaviour.", [[1, "observ|imitat|model", "Observation and imitation of models"], [1, "vicarious reinforcement|rewarded", "Vicarious reinforcement"], [1, "attention|retention|reproduction|motivation", "Mediating processes"], [1, "bandura|bobo", "Bandura's Bobo doll study"]], "People observe and imitate role models; if the model is rewarded (vicarious reinforcement) the behaviour is more likely to be copied. Imitation depends on attention, retention, reproduction and motivation. Bandura's Bobo doll study showed children copied aggression."),
  q("Statistics", "calculate", 2, "Scores: 4, 7, 7, 9, 13. Calculate the mean and the mode.", [[1, "8", "Mean = 8"], [1, "7", "Mode = 7"]], "Mean = 40 ÷ 5 = 8; mode = 7."),
  q("Development", "evaluate", 6, "Evaluate Piaget's theory of cognitive development.", [[1, "influential|education|discovery learning", "Strength: influenced education"], [1, "research|three mountains|conservation", "Supported by research (conservation tasks)"], [1, "underestimated|younger|hughes|policeman", "Weakness: underestimated children (Hughes)"], [1, "culture|social|vygotsky", "Ignores social/cultural factors"], [1, "however|on the other hand", "Balanced"], [1, "overall|in conclusion", "Judgement"]], "Piaget's theory has been very influential in education (discovery learning) and is supported by conservation tasks. However, Hughes' policeman doll study suggests he underestimated young children, and he ignored social and cultural factors that Vygotsky stressed. Overall it remains useful but should be combined with other theories.")
], ED);

